#!/usr/bin/env python3
"""Focused static regression check for the CVE-2024-45341 port.

This is a source-structure check, NOT a Go build or test. It asserts the
security-relevant guard in matchURIConstraint and the regression-test case,
and models the guard decision for the sample host using the documented
semantics of net.ParseIP (no zones) vs netip.ParseAddr (zones).

Usage: focused_static_check.py <verify.go> <name_constraints_test.go> <mode>
where mode is 'candidate' or 'baseline'.
"""
import re
import sys


def extract_func(src: str, name: str) -> str:
    m = re.search(r"^func " + re.escape(name) + r"\(.*?^}\n", src, re.S | re.M)
    if not m:
        raise SystemExit(f"function {name} not found")
    return m.group(0)


def model_net_parse_ip(host: str):
    """net.ParseIP does not understand '%zone'; returns None for the sample.

    Faithful for the tested input: any '%' makes ParseIP fail (it only accepts
    a bare IPv6 or IPv4 literal)."""
    if "%" in host:
        return None
    body = host.strip("[]")
    if ":" in body:
        return "ipv6" if re.fullmatch(r"[0-9A-Fa-f:.]+", body) else None
    return "ipv4" if re.fullmatch(r"\d+\.\d+\.\d+\.\d+", body) else None


def model_netip_parse_addr(host: str):
    """netip.ParseAddr understands '%zone' and rejects the bracketed form."""
    if host.startswith("[") or host.endswith("]"):
        return None
    body, _, zone = host.partition("%")
    if not body:
        return None
    if ":" in body and re.fullmatch(r"[0-9A-Fa-f:.]+", body):
        return ("ipv6", zone if zone else None)
    return None


def main() -> int:
    verify_path, test_path, mode = sys.argv[1], sys.argv[2], sys.argv[3]
    verify = open(verify_path, encoding="utf-8").read()
    test = open(test_path, encoding="utf-8").read()
    match = extract_func(verify, "matchURIConstraint")

    failures = []
    import_ok = '"net/netip"' in verify
    new_guard = "netip.ParseAddr(host)" in match
    old_guard = "net.ParseIP(host)" in match
    bracket_clause = (
        'strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]")' in match
    )
    test_case = "uri:http://[2006:abcd::1%25.example.com]:16/" in test
    expected = 'expectedError: "URI with IP"' in test

    if mode == "candidate":
        if not import_ok:
            failures.append("candidate: missing net/netip import")
        if not new_guard:
            failures.append("candidate: netip.ParseAddr guard absent")
        if old_guard:
            failures.append("candidate: legacy net.ParseIP guard still present")
        if not bracket_clause:
            failures.append("candidate: bracketed-literal clause absent")
        if not test_case:
            failures.append("candidate: regression URI test case absent")
        if not expected:
            failures.append("candidate: 'URI with IP' expectation absent")
    elif mode == "baseline":
        if import_ok:
            failures.append("baseline unexpectedly imports net/netip")
        if new_guard:
            failures.append("baseline unexpectedly has netip.ParseAddr guard")
        if not old_guard:
            failures.append("baseline: legacy net.ParseIP guard absent")
        if test_case:
            failures.append("baseline unexpectedly has the regression test")
    else:
        raise SystemExit("mode must be candidate or baseline")

    # Model the vulnerable host decision. This reproduces the *logic* of the
    # guard using documented net/netip semantics; it is not a Go execution.
    sample = "2006:abcd::1%.example.com"  # post-SplitHostPort host
    old_reject = (sample.startswith("[") and sample.endswith("]")) or model_net_parse_ip(sample) is not None
    new_reject = model_netip_parse_addr(sample) is not None or (sample.startswith("[") and sample.endswith("]"))
    model_ok = (old_reject is False) and (new_reject is True)

    print(f"mode={mode}")
    print(f"  net/netip import: {import_ok}")
    print(f"  netip.ParseAddr guard: {new_guard}")
    print(f"  legacy net.ParseIP guard: {old_guard}")
    print(f"  bracket clause: {bracket_clause}")
    print(f"  regression test case: {test_case}")
    print(f"  model sample {sample!r}: old_reject={old_reject} new_reject={new_reject} model_ok={model_ok}")
    if failures:
        for f in failures:
            print("FAIL:", f)
        return 1
    if mode == "candidate" and not model_ok:
        print("FAIL: logic model did not reproduce vulnerability closure")
        return 1
    print("RESULT: pass")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

